  const phoneW = phoneH / 2.16; // Standard modern smartphone ratio

  // Animation Timing
  const START_DELAY = fps * 1.5; // Wait 1.5s for sheet to slide up before transcribing
  const activeFrame = Math.max(0, frame - START_DELAY);
  
  // Calculate total words to distribute typing speed
  let currentWordCount = 0;
  const messagesWithTiming = useMemo(() => {
    return messages.map(m => {
      const wordsCount = m.text.split(" ").length;
      const startWordIndex = currentWordCount;
      currentWordCount += wordsCount;
      return { ...m, startWordIndex };
    });
  }, [messages]);

  const totalWords = currentWordCount;
